input.command:
cd /tmp && node <<'JS'
const { chromium } = require('/tmp/node_modules/playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
  const fixture = 'file://' + path.resolve('/Users/sinchunyeung/github/simplification-of-trajectory-streams/web/usability/step-segment-green-path.html');
  await page.goto(fixture, { waitUntil: 'networkidle' });
  const check = await page.textContent('#check');
  console.log('fixture:', check);
  await page.screenshot({ path: '/Users/sinchunyeung/github/simplification-of-trajectory-streams/web/usability/step-segment-green-path.png', fullPage: true });

  // Spot-check live index+viewer strings via file read in page
  const indexPath = 'file://' + path.resolve('/Users/sinchunyeung/github/simplification-of-trajectory-streams/web/index.html');
  await page.goto(indexPath, { waitUntil: 'domcontentloaded' });
  const live = await page.evaluate(() => {
    const gloss = document.getElementById('playbackInstructionsGloss')?.innerText || '';
    const stepCap = document.querySelector('#stepInput')?.closest('.pb-nav')?.querySelector('.pb-caption')?.getAttribute('title') || '';
    const segCap = document.querySelector('#segmentInput')?.closest('.pb-nav')?.querySelector('.pb-caption')?.getAttribute('title') || '';
    const stepAria = document.getElementById('mobileStepForwardBtn')?.getAttribute('aria-label') || '';
    const segAria = document.getElementById('mobileSegmentForwardBtn')?.getAttribute('aria-label') || '';
    return {
      gloss,
      stepCap,
      segCap,
      stepAria,
      segAria,
      hasOld: (gloss + stepCap + segCap + stepAria + segAria).includes('simplified piece')
        || (gloss + stepCap + segCap).includes('pieces of the simplified'),
      scrollWidth: document.documentElement.scrollWidth,
    };
  });
  console.log('live index:', JSON.stringify(live, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
